import React, { useState } from 'react';
import { FiMenu, FiClipboard, FiPlus, FiFileText, FiFolderPlus, FiHome, FiBookOpen, FiHelpCircle } from 'react-icons/fi';
import './index.css';

function NavItem({ icon, label, active, sidebarOpen }) {
  return (
    <div className={`flex items-center px-4 py-3 hover:bg-blue-800 cursor-pointer transition ${active ? 'bg-blue-700' : ''}`}>
      <span className="text-lg">{icon}</span>
      {sidebarOpen && <span className="ml-3 font-medium">{label}</span>}
    </div>
  );
}

export default function TradeJournalApp() {
  const [view, setView] = useState('Trades');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar */}
      <aside className={`${sidebarOpen ? 'w-64' : 'w-16'} transition-width duration-300 bg-blue-900 text-white flex-shrink-0`}>  
        <div className="flex items-center px-4 py-6">
          <span className={`${sidebarOpen ? 'block' : 'hidden'} text-2xl font-bold`}>CHART<span className="text-green-400">MAZE</span></span>
          <button onClick={() => setSidebarOpen(open => !open)} className="ml-auto focus:outline-none">
            <FiMenu size={20} />
          </button>
        </div>
        <nav className="mt-4">
          <NavItem icon={<FiBookOpen />} label="My Rule Book" sidebarOpen={sidebarOpen} />
          <NavItem icon={<FiPlus />} label="Add Trades" sidebarOpen={sidebarOpen} />
          <NavItem icon={<FiClipboard />} label="Manage Trades" sidebarOpen={sidebarOpen} />
          <NavItem icon={<FiFolderPlus />} label="Open Positions" sidebarOpen={sidebarOpen} />
          <NavItem icon={<FiHome />} label="Dashboard" sidebarOpen={sidebarOpen} />
          <NavItem icon={<FiFileText />} label="Trade Diary" sidebarOpen={sidebarOpen} active />
          <NavItem icon={<FiClipboard />} label="ChartsMaze Screener" sidebarOpen={sidebarOpen} />
          <NavItem icon={<FiHelpCircle />} label="Help or Feedback" sidebarOpen={sidebarOpen} />
        </nav>
        <div className="mt-auto px-4 py-6">
          <button className="w-full py-2 bg-green-400 rounded-full font-semibold">
            {sidebarOpen ? 'Login' : <FiClipboard />}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 overflow-auto">
        <header className="flex items-center px-8 py-4 bg-white shadow">
          <h1 className="flex-1 text-xl font-bold text-blue-600">Welcome to ChartsMaze Trade Journal</h1>
        </header>

        <main className="p-8">
          <p className="text-center text-gray-700 mb-6">
            To start tracking your trades and get valuable insights into your trading performance, please log in to your account.
          </p>
          <div className="flex justify-center mb-12">
            <button className="px-6 py-3 bg-green-400 text-white font-semibold rounded-full shadow-lg hover:bg-green-500 transition">
              Log in to Continue
            </button>
          </div>

          <h2 className="text-center text-lg font-semibold text-gray-800 mb-4">See How It Works</h2>
          <div className="flex justify-center">
            <div className="w-full max-w-3xl aspect-video bg-black rounded overflow-hidden shadow-lg">
              <iframe
                className="w-full h-full"
                src="https://www.youtube.com/embed/re2zTJyJqDg?start=1"
                title="How it works"
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              />
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
